-- Order 4 additive preparation. No role/default/override grants.
CREATE TABLE public.sales_resource_catalog(table_name name PRIMARY KEY,resource text NOT NULL,responsibles text[] NOT NULL,shared boolean NOT NULL,parent_table name,parent_column name,id_column name);
ALTER TABLE public.sales_resource_catalog ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.sales_resource_catalog FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.sales_access_context()
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT public.work_access_context() $$;
REVOKE ALL ON FUNCTION public.sales_access_context() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.sales_access_context() TO authenticated;
CREATE OR REPLACE FUNCTION public.sales_context_access(c jsonb,w uuid,r text,a text,responsibles uuid[])
RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public,pg_temp AS $$
 SELECT coalesce(c->>'workspace'=w::text AND c->>'actor' IS NOT NULL
 AND r=ANY(ARRAY['system.analytics.dashboards','system.analytics.insights','system.analytics.reports','system.automation.email_templates','system.automation.rotation','system.automation.sequences','system.automation.sla','system.booking','system.calendars','system.hubspot_sync','system.import','system.integration_sync','system.integrations','system.linkedin','system.pipelines','system.portal','system.snippets','system.webhooks','system.whatsapp','system.workflows','techsales.activities','techsales.ai_assist','techsales.campaign_dispatch','techsales.communications','techsales.companies','techsales.contacts','techsales.conversion','techsales.dashboard','techsales.deal_loss_reasons','techsales.deals','techsales.email_accounts','techsales.goals','techsales.inbox.chat','techsales.inbox.email','techsales.inbox.whatsapp','techsales.lead_sources','techsales.leads','techsales.marketing.campaigns','techsales.marketing.forms','techsales.marketing.landing_pages','techsales.marketing.sdr_agent','techsales.meeting_settings','techsales.meetings','techsales.notes','techsales.proposal_clauses','techsales.proposal_send','techsales.proposal_share','techsales.proposal_templates','techsales.proposals','techsales.prospecting_cadences','techsales.prospecting_enrichment','techsales.prospecting_playbooks','techsales.prospecting_qualifications','techsales.prospecting_questionnaires','techsales.prospecting_queue','techsales.prospecting_scoring','techsales.prospecting_scripts','techsales.prospecting_search','techsales.prospecting_voice','techsales.quote_send','techsales.quote_share','techsales.quote_templates','techsales.quotes','techsales.segments','techsales.surveys','techsales.task_queues','techsales.tasks','techsales.tickets']::text[])
 AND a IN('view','create','update','delete','assign','approve','export','manage')
 AND (a='view' OR NOT coalesce((c->>'read_only')::boolean,true)
   OR (r IN('techsales.leads','techsales.contacts','techsales.companies','techsales.deals','techsales.activities','techsales.notes','techsales.tasks') AND a IN('create','update','delete','assign')))
 AND (c->'keys' ? (r||'.'||a||'.workspace')
 OR (c->'keys' ? (r||'.'||a||'.own') AND (c->>'actor')::uuid=ANY(responsibles))
 OR (c->'keys' ? (r||'.'||a||'.team') AND ((c->>'actor')::uuid=ANY(responsibles) OR EXISTS(SELECT 1 FROM unnest(responsibles)x WHERE c->'team'?x::text)))),false)
$$;
REVOKE ALL ON FUNCTION public.sales_context_access(jsonb,uuid,text,text,uuid[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.sales_context_access(jsonb,uuid,text,text,uuid[]) TO authenticated;
-- Context-bearing recursive helper is private; callers cannot supply forged keys.
CREATE OR REPLACE FUNCTION public.sales_record_context_access(c jsonb,t text,i uuid,a text,depth integer DEFAULT 0)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE m sales_resource_catalog;j jsonb;p jsonb;s uuid[];w uuid;rr text;BEGIN
 IF depth>5 OR c->>'actor' IS NULL OR i IS NULL THEN RETURN false;END IF;
 SELECT * INTO m FROM sales_resource_catalog WHERE table_name=t;
 IF NOT FOUND OR m.id_column IS NULL THEN RETURN false;END IF;
 EXECUTE format('SELECT to_jsonb(x) FROM public.%I x WHERE %I=$1',m.table_name,m.id_column) INTO j USING i;
 IF j IS NULL THEN RETURN false;END IF;
 w:=nullif(j->>'workspace_id','')::uuid;
 IF w IS NOT NULL AND w::text IS DISTINCT FROM c->>'workspace' THEN RETURN false;END IF;
 IF m.parent_table IS NOT NULL THEN
  IF a='view' THEN RETURN sales_record_context_access(c,m.parent_table::text,nullif(j->>m.parent_column::text,'')::uuid,'view',depth+1);END IF;
  RETURN sales_record_context_access(c,m.parent_table::text,nullif(j->>m.parent_column::text,'')::uuid,'view',depth+1)
    AND (sales_record_context_access(c,m.parent_table::text,nullif(j->>m.parent_column::text,'')::uuid,'update',depth+1)
      OR (a='create' AND sales_record_context_access(c,m.parent_table::text,nullif(j->>m.parent_column::text,'')::uuid,'create',depth+1)));
 END IF;
 SELECT ARRAY(SELECT nullif(j->>x,'')::uuid FROM unnest(m.responsibles)x WHERE nullif(j->>x,'') IS NOT NULL LIMIT 1) INTO s;
 rr:=CASE WHEN t='activities' AND j->>'type'='note' THEN 'techsales.notes' WHEN t='activities' AND j->>'type'='task' THEN 'techsales.tasks' ELSE m.resource END;
 RETURN sales_context_access(c,w,rr,a,s)
   AND (a='view' OR sales_context_access(c,w,rr,'view',s));
END $$;
REVOKE ALL ON FUNCTION public.sales_record_context_access(jsonb,text,uuid,text,integer) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.sales_record_access(t text,i uuid,a text)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT public.sales_record_context_access(public.sales_access_context(),t,i,a)
$$;
REVOKE ALL ON FUNCTION public.sales_record_access(text,uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.sales_record_access(text,uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.sales_area_authorize(r text,a text,t text DEFAULT NULL,i uuid DEFAULT NULL)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c jsonb:=sales_access_context();w uuid:=(c->>'workspace')::uuid;s uuid[]:=ARRAY[(c->>'actor')::uuid];BEGIN
 IF w IS NULL OR NOT sales_context_access(c,w,r,'view',s)
 OR NOT (c->'keys' ?| ARRAY[r||'.'||a||'.own',r||'.'||a||'.team',r||'.'||a||'.workspace'])
 OR (a<>'view' AND coalesce((c->>'read_only')::boolean,true) AND NOT(r IN('techsales.leads','techsales.contacts','techsales.companies','techsales.deals','techsales.activities','techsales.notes','techsales.tasks') AND a IN('create','update','delete','assign')))
 OR (i IS NOT NULL AND (t IS NULL OR NOT EXISTS(SELECT 1 FROM sales_resource_catalog WHERE table_name=t AND (resource=r OR (t='activities' AND r IN('techsales.notes','techsales.tasks')))) OR NOT sales_record_context_access(c,t,i,a)))
 THEN RAISE EXCEPTION 'Sem permissão para esta ação comercial.' USING ERRCODE='42501';END IF;
 RETURN true;
END $$;
REVOKE ALL ON FUNCTION public.sales_area_authorize(text,text,text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.sales_area_authorize(text,text,text,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.sales_capabilities(t text,ids uuid[])
RETURNS TABLE(id uuid,can_view boolean,can_update boolean,can_delete boolean,can_assign boolean,can_approve boolean,can_export boolean,can_manage boolean)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c jsonb:=sales_access_context();i uuid;BEGIN
 IF coalesce(cardinality(ids),0)>500 OR NOT EXISTS(SELECT 1 FROM sales_resource_catalog WHERE table_name=t AND id_column IS NOT NULL) THEN RAISE EXCEPTION 'Consulta inválida.';END IF;
 FOREACH i IN ARRAY coalesce(ids,'{}') LOOP
 IF sales_record_context_access(c,t,i,'view') THEN RETURN QUERY SELECT i,true,sales_record_context_access(c,t,i,'update'),sales_record_context_access(c,t,i,'delete'),sales_record_context_access(c,t,i,'assign'),sales_record_context_access(c,t,i,'approve'),sales_record_context_access(c,t,i,'export'),sales_record_context_access(c,t,i,'manage');END IF;
 END LOOP;
END $$;
REVOKE ALL ON FUNCTION public.sales_capabilities(text,uuid[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.sales_capabilities(text,uuid[]) TO authenticated;
-- User-facing capabilities must execute as the caller: retain every existing
-- restrictive policy (restricted job visibility, test isolation and read-only).
CREATE OR REPLACE FUNCTION public.sales_record_access(t text,i uuid,a text)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=public,pg_temp AS $$
DECLARE c jsonb:=sales_access_context();BEGIN
 IF i IS NULL OR a NOT IN('view','create','update','delete','assign','approve','export','manage') THEN RETURN false;END IF;
 CASE t
WHEN 'tickets' THEN RETURN EXISTS(SELECT 1 FROM public."tickets" WHERE "id"=i AND (public.sales_context_access(c,"tickets".workspace_id,'techsales.tickets',a,ARRAY[coalesce("tickets"."assignee_id","tickets"."owner_id")]::uuid[])));
WHEN 'slack_event_routes' THEN RETURN EXISTS(SELECT 1 FROM public."slack_event_routes" WHERE "id"=i AND (public.sales_context_access(c,"slack_event_routes".workspace_id,'system.integrations',a,ARRAY["slack_event_routes"."owner_id"]::uuid[])));
WHEN 'leads' THEN RETURN EXISTS(SELECT 1 FROM public."leads" WHERE "id"=i AND (public.sales_context_access(c,"leads".workspace_id,'techsales.leads',a,ARRAY[coalesce("leads"."assigned_to","leads"."owner_id")]::uuid[])));
WHEN 'contacts' THEN RETURN EXISTS(SELECT 1 FROM public."contacts" WHERE "id"=i AND (public.sales_context_access(c,"contacts".workspace_id,'techsales.contacts',a,ARRAY[coalesce("contacts"."assigned_to","contacts"."owner_id")]::uuid[])));
WHEN 'companies' THEN RETURN EXISTS(SELECT 1 FROM public."companies" WHERE "id"=i AND (public.sales_context_access(c,"companies".workspace_id,'techsales.companies',a,ARRAY[coalesce("companies"."assigned_to","companies"."owner_id")]::uuid[])));
WHEN 'deals' THEN RETURN EXISTS(SELECT 1 FROM public."deals" WHERE "id"=i AND (public.sales_context_access(c,"deals".workspace_id,'techsales.deals',a,ARRAY[coalesce("deals"."assigned_to","deals"."owner_id")]::uuid[])));
WHEN 'activities' THEN RETURN EXISTS(SELECT 1 FROM public."activities" WHERE "id"=i AND (public.sales_context_access(c,"activities".workspace_id,(CASE WHEN "activities".type::text='note' THEN 'techsales.notes' WHEN "activities".type::text='task' THEN 'techsales.tasks' ELSE 'techsales.activities' END),a,ARRAY[coalesce("activities"."assigned_to","activities"."owner_id")]::uuid[])));
WHEN 'quotes' THEN RETURN EXISTS(SELECT 1 FROM public."quotes" WHERE "id"=i AND (public.sales_context_access(c,"quotes".workspace_id,'techsales.quotes',a,ARRAY[coalesce("quotes"."assigned_to","quotes"."owner_id")]::uuid[])));
WHEN 'proposals' THEN RETURN EXISTS(SELECT 1 FROM public."proposals" WHERE "id"=i AND (public.sales_context_access(c,"proposals".workspace_id,'techsales.proposals',a,ARRAY[coalesce("proposals"."assigned_to","proposals"."owner_id")]::uuid[])));
