WHEN 'prospecting_cadences' THEN RETURN EXISTS(SELECT 1 FROM public."prospecting_cadences" WHERE "id"=i AND (public.sales_context_access(c,"prospecting_cadences".workspace_id,'techsales.prospecting_cadences',a,ARRAY[coalesce("prospecting_cadences"."assigned_to","prospecting_cadences"."owner_id")]::uuid[])));
WHEN 'prospecting_questionnaires' THEN RETURN EXISTS(SELECT 1 FROM public."prospecting_questionnaires" WHERE "id"=i AND (public.sales_context_access(c,"prospecting_questionnaires".workspace_id,'techsales.prospecting_questionnaires',a,ARRAY[coalesce("prospecting_questionnaires"."assigned_to","prospecting_questionnaires"."owner_id")]::uuid[])));
