WHEN 'sdr_workspace_settings' THEN RETURN EXISTS(SELECT 1 FROM public.sdr_workspace_settings WHERE workspace_id=i AND CASE a WHEN 'view' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.marketing.sdr_agent','view',ARRAY[]::uuid[])) WHEN 'create' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.marketing.sdr_agent','manage',ARRAY[]::uuid[]) AND public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.marketing.sdr_agent','view',ARRAY[]::uuid[])) WHEN 'update' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.marketing.sdr_agent','manage',ARRAY[]::uuid[]) AND public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.marketing.sdr_agent','view',ARRAY[]::uuid[])) WHEN 'delete' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.marketing.sdr_agent','manage',ARRAY[]::uuid[]) AND public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.marketing.sdr_agent','view',ARRAY[]::uuid[])) WHEN 'manage' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.marketing.sdr_agent','manage',ARRAY[]::uuid[]) AND public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.marketing.sdr_agent','view',ARRAY[]::uuid[])) WHEN 'approve' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.marketing.sdr_agent','manage',ARRAY[]::uuid[]) AND public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.marketing.sdr_agent','view',ARRAY[]::uuid[])) WHEN 'export' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.marketing.sdr_agent','manage',ARRAY[]::uuid[]) AND public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.marketing.sdr_agent','view',ARRAY[]::uuid[])) WHEN 'assign' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.marketing.sdr_agent','manage',ARRAY[]::uuid[]) AND public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.marketing.sdr_agent','view',ARRAY[]::uuid[])) ELSE false END);
WHEN 'voice_agent_settings' THEN RETURN EXISTS(SELECT 1 FROM public.voice_agent_settings WHERE workspace_id=i AND CASE a WHEN 'view' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.prospecting_voice','view',ARRAY[owner_id]::uuid[])) WHEN 'create' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.prospecting_voice','create',ARRAY[owner_id]::uuid[]) AND public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.prospecting_voice','view',ARRAY[owner_id]::uuid[])) WHEN 'update' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.prospecting_voice','update',ARRAY[owner_id]::uuid[]) AND public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.prospecting_voice','view',ARRAY[owner_id]::uuid[])) WHEN 'delete' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.prospecting_voice','delete',ARRAY[owner_id]::uuid[]) AND public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.prospecting_voice','view',ARRAY[owner_id]::uuid[])) WHEN 'manage' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.prospecting_voice','manage',ARRAY[owner_id]::uuid[]) AND public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.prospecting_voice','view',ARRAY[owner_id]::uuid[])) WHEN 'approve' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.prospecting_voice','approve',ARRAY[owner_id]::uuid[]) AND public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.prospecting_voice','view',ARRAY[owner_id]::uuid[])) WHEN 'export' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.prospecting_voice','export',ARRAY[owner_id]::uuid[]) AND public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.prospecting_voice','view',ARRAY[owner_id]::uuid[])) WHEN 'assign' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.prospecting_voice','assign',ARRAY[owner_id]::uuid[]) AND public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.prospecting_voice','view',ARRAY[owner_id]::uuid[])) ELSE false END);
WHEN 'ml_scoring_models' THEN RETURN EXISTS(SELECT 1 FROM public.ml_scoring_models WHERE owner_id=i AND CASE a WHEN 'view' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.prospecting_scoring','view',ARRAY[owner_id]::uuid[])) WHEN 'create' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.prospecting_scoring','create',ARRAY[owner_id]::uuid[]) AND public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.prospecting_scoring','view',ARRAY[owner_id]::uuid[])) WHEN 'update' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.prospecting_scoring','update',ARRAY[owner_id]::uuid[]) AND public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.prospecting_scoring','view',ARRAY[owner_id]::uuid[])) WHEN 'delete' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.prospecting_scoring','delete',ARRAY[owner_id]::uuid[]) AND public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.prospecting_scoring','view',ARRAY[owner_id]::uuid[])) WHEN 'manage' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.prospecting_scoring','manage',ARRAY[owner_id]::uuid[]) AND public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.prospecting_scoring','view',ARRAY[owner_id]::uuid[])) WHEN 'approve' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.prospecting_scoring','approve',ARRAY[owner_id]::uuid[]) AND public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.prospecting_scoring','view',ARRAY[owner_id]::uuid[])) WHEN 'export' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.prospecting_scoring','export',ARRAY[owner_id]::uuid[]) AND public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.prospecting_scoring','view',ARRAY[owner_id]::uuid[])) WHEN 'assign' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.prospecting_scoring','assign',ARRAY[owner_id]::uuid[]) AND public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.prospecting_scoring','view',ARRAY[owner_id]::uuid[])) ELSE false END);
WHEN 'workflow_send_policies' THEN RETURN EXISTS(SELECT 1 FROM public.workflow_send_policies WHERE workspace_id=i AND CASE a WHEN 'view' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'system.workflows','view',ARRAY[]::uuid[])) WHEN 'create' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'system.workflows','manage',ARRAY[]::uuid[]) AND public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'system.workflows','view',ARRAY[]::uuid[])) WHEN 'update' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'system.workflows','manage',ARRAY[]::uuid[]) AND public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'system.workflows','view',ARRAY[]::uuid[])) WHEN 'delete' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'system.workflows','manage',ARRAY[]::uuid[]) AND public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'system.workflows','view',ARRAY[]::uuid[])) WHEN 'manage' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'system.workflows','manage',ARRAY[]::uuid[]) AND public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'system.workflows','view',ARRAY[]::uuid[])) WHEN 'approve' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'system.workflows','manage',ARRAY[]::uuid[]) AND public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'system.workflows','view',ARRAY[]::uuid[])) WHEN 'export' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'system.workflows','manage',ARRAY[]::uuid[]) AND public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'system.workflows','view',ARRAY[]::uuid[])) WHEN 'assign' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'system.workflows','manage',ARRAY[]::uuid[]) AND public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'system.workflows','view',ARRAY[]::uuid[])) ELSE false END);
WHEN 'sdr_agent_identities' THEN RETURN EXISTS(SELECT 1 FROM public.sdr_agent_identities WHERE user_id=i AND CASE a WHEN 'view' THEN (public.sales_context_access((SELECT public.sales_access_context()),workspace_id,'techsales.marketing.sdr_agent','view',ARRAY[]::uuid[])) WHEN 'create' THEN (false) WHEN 'update' THEN (false) WHEN 'delete' THEN (false) WHEN 'manage' THEN (false) WHEN 'approve' THEN (false) WHEN 'export' THEN (false) WHEN 'assign' THEN (false) ELSE false END);
ELSE RETURN false;END CASE;END $$;
CREATE OR REPLACE FUNCTION public.sales_capabilities(t text,ids uuid[])
RETURNS TABLE(id uuid,can_view boolean,can_update boolean,can_delete boolean,can_assign boolean,can_approve boolean,can_export boolean,can_manage boolean)
LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=public,pg_temp AS $$
DECLARE i uuid;BEGIN
 IF coalesce(cardinality(ids),0)>500 THEN RAISE EXCEPTION 'Limite excedido.';END IF;
 FOREACH i IN ARRAY coalesce(ids,'{}') LOOP
 IF sales_record_access(t,i,'view') THEN RETURN QUERY SELECT i,true,sales_record_access(t,i,'update'),sales_record_access(t,i,'delete'),sales_record_access(t,i,'assign'),sales_record_access(t,i,'approve'),sales_record_access(t,i,'export'),sales_record_access(t,i,'manage');END IF;
 END LOOP;END $$;
CREATE OR REPLACE FUNCTION public.sales_area_authorize(r text,a text,t text DEFAULT NULL,i uuid DEFAULT NULL)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=public,pg_temp AS $$
DECLARE c jsonb:=sales_access_context();w uuid:=(c->>'workspace')::uuid;s uuid[]:=ARRAY[(c->>'actor')::uuid];BEGIN
 IF w IS NULL OR NOT sales_context_access(c,w,r,'view',s)
 OR NOT (c->'keys' ?| ARRAY[r||'.'||a||'.own',r||'.'||a||'.team',r||'.'||a||'.workspace'])
 OR (a<>'view' AND coalesce((c->>'read_only')::boolean,true) AND NOT(r IN('techsales.leads','techsales.contacts','techsales.companies','techsales.deals','techsales.activities','techsales.notes','techsales.tasks') AND a IN('create','update','delete','assign')))
 OR (i IS NOT NULL AND (t IS NULL OR NOT sales_record_access(t,i,a)))
 THEN RAISE EXCEPTION 'Sem permissão para esta ação comercial.' USING ERRCODE='42501';END IF;
 RETURN true;END $$;

-- Technical lookup for authorized commercial users: stage IDs/names only,
-- never granting full pipeline configuration or any CRM business row.
CREATE OR REPLACE FUNCTION public.sales_pipeline_references()
RETURNS TABLE(id uuid,owner_id uuid,workspace_id uuid,entity text,name text,is_default boolean,stages jsonb,default_view text,created_at timestamptz,updated_at timestamptz)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c jsonb:=sales_access_context();w uuid:=(c->>'workspace')::uuid;BEGIN
 IF w IS NULL OR NOT EXISTS(SELECT 1 FROM jsonb_object_keys(c->'keys')k WHERE k ~ '^(techsales\.(leads|contacts|companies|deals|tickets)\.(view|create|update)|system\.pipelines\.view)\.(own|team|workspace)$') THEN RETURN;END IF;
 RETURN QUERY SELECT p.id,p.owner_id,p.workspace_id,p.entity,p.name,p.is_default,p.stages,p.default_view,p.created_at,p.updated_at FROM pipelines p WHERE p.workspace_id=w ORDER BY p.name,p.id;
END $$;
REVOKE ALL ON FUNCTION public.sales_pipeline_references() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.sales_pipeline_references() TO authenticated;
-- API key scope is intersected with the current owner's actual RLS/permissions.
-- The execution owner inherits authenticated and has NOBYPASSRLS; service_role
-- can enter this port but cannot choose an unchecked user/workspace/key tuple.
CREATE OR REPLACE FUNCTION techerp_api.sales_filter(p_table text,f jsonb,depth integer DEFAULT 0)
RETURNS text LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=public,pg_temp AS $$
DECLARE field text:=f->>'field';base text;path text;op text:=f->>'op';value jsonb:=f->'value';expr text;parts text[];item jsonb;BEGIN
 IF depth>8 THEN RAISE EXCEPTION 'Filtro muito complexo.' USING ERRCODE='22023';END IF;
 IF op IN('or','and') THEN
  IF jsonb_typeof(value)<>'array' OR jsonb_array_length(value)>100 THEN RAISE EXCEPTION 'Filtro inválido.';END IF;
  FOR item IN SELECT * FROM jsonb_array_elements(value) LOOP parts:=array_append(parts,techerp_api.sales_filter(p_table,item,depth+1));END LOOP;
  RETURN '('||coalesce(array_to_string(parts,CASE WHEN op='or' THEN ' OR ' ELSE ' AND ' END),'false')||')';
 END IF;
 base:=split_part(field,'->>',1);path:=CASE WHEN position('->>' IN field)>0 THEN split_part(field,'->>',2) END;
 IF base !~ '^[a-z_][a-z0-9_]*$' OR NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name=p_table AND column_name=base) THEN RAISE EXCEPTION 'Campo de filtro inválido.';END IF;
 IF base IN('portal_token','public_token','access_token','refresh_token','oauth_tokens','credentials_secret_ref','secret') THEN RAISE EXCEPTION 'Campo privado.' USING ERRCODE='42501';END IF;
 expr:=format('%I',base);
 IF path IS NOT NULL THEN
  IF path !~ '^[a-z_][a-z0-9_]*$' THEN RAISE EXCEPTION 'Caminho inválido.';END IF;
  expr:=expr||'->>'||quote_literal(path);
 END IF;
 IF op='is' AND (value IS NULL OR value='null'::jsonb) THEN RETURN expr||' IS NULL';END IF;
 IF op='in' THEN
  IF jsonb_typeof(value)<>'array' OR jsonb_array_length(value)>1000 THEN RAISE EXCEPTION 'Lista de filtro inválida.';END IF;
  SELECT array_agg(quote_literal(x)) INTO parts FROM jsonb_array_elements_text(value)x;
  RETURN CASE WHEN cardinality(parts)>0 THEN expr||' IN ('||array_to_string(parts,',')||')' ELSE 'false' END;
 END IF;
 IF op='contains' THEN RETURN expr||' @> '||quote_literal(value::text)||'::jsonb';END IF;
 IF op NOT IN('eq','neq','gt','gte','lt','lte','like','ilike','is') THEN RAISE EXCEPTION 'Operador inválido.';END IF;
 RETURN expr||CASE op WHEN 'eq' THEN '=' WHEN 'neq' THEN '<>' WHEN 'gt' THEN '>' WHEN 'gte' THEN '>=' WHEN 'lt' THEN '<' WHEN 'lte' THEN '<=' WHEN 'like' THEN ' LIKE ' WHEN 'ilike' THEN ' ILIKE ' WHEN 'is' THEN ' IS ' END||quote_nullable(value#>>'{}');
END $$;
REVOKE ALL ON FUNCTION techerp_api.sales_filter(text,jsonb,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION techerp_api.sales_filter(text,jsonb,integer) TO techerp_api_subject;
CREATE OR REPLACE FUNCTION techerp_api.sales_query(p_key uuid,p_user uuid,p_ws uuid,p_table text,p_query jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE op text:=coalesce(p_query->>'operation','select');filters jsonb:=coalesce(p_query->'filters','[]');payload jsonb:=p_query->'payload';f jsonb;columns text[];selections text[];key text;predicate text:='true';ordering text:='';selected text;sql text;source text;resource text;rows jsonb;n bigint;lim integer:=least(greatest(coalesce((p_query->>'limit')::integer,200),0),1000);off integer:=greatest(coalesce((p_query->>'offset')::integer,0),0);BEGIN
 IF p_table NOT IN('leads','contacts','companies','deals','activities','meetings','pipelines','deal_line_items','deal_contacts') OR op NOT IN('select','insert','update','delete') THEN RAISE EXCEPTION 'Operação da API indisponível.' USING ERRCODE='42501';END IF;
 PERFORM techerp_api.enter(p_key,p_user,p_ws);
 source:=CASE WHEN p_table='pipelines' AND op='select' THEN 'public.sales_pipeline_references()' ELSE 'public.'||quote_ident(p_table) END;
 resource:=CASE p_table WHEN 'leads' THEN 'techsales.leads' WHEN 'contacts' THEN 'techsales.contacts' WHEN 'companies' THEN 'techsales.companies' WHEN 'deals' THEN 'techsales.deals' WHEN 'deal_contacts' THEN 'techsales.deals' WHEN 'deal_line_items' THEN 'techsales.deals' WHEN 'meetings' THEN 'techsales.meetings' WHEN 'activities' THEN CASE WHEN payload->>'type'='note' THEN 'techsales.notes' WHEN payload->>'type'='task' THEN 'techsales.tasks' ELSE 'techsales.activities' END ELSE 'system.pipelines' END;
 IF NOT(p_table='pipelines' AND op='select') THEN PERFORM sales_area_authorize(resource,CASE op WHEN 'select' THEN 'view' WHEN 'insert' THEN 'create' WHEN 'delete' THEN 'delete' ELSE 'update' END);END IF;
 IF NOT EXISTS(SELECT 1 FROM api_keys WHERE id=p_key AND (scopes @> ARRAY['write']::text[] OR (op='select' AND scopes @> ARRAY['read']::text[]))) THEN RAISE EXCEPTION 'Escopo da chave insuficiente.' USING ERRCODE='42501';END IF;
 IF jsonb_typeof(filters)<>'array' OR jsonb_array_length(filters)>100 THEN RAISE EXCEPTION 'Filtros inválidos.';END IF;
 FOR f IN SELECT * FROM jsonb_array_elements(filters) LOOP predicate:=predicate||' AND ('||techerp_api.sales_filter(p_table,f)||')';END LOOP;
 IF EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name=p_table AND column_name='workspace_id') THEN predicate:=predicate||format(' AND workspace_id=%L::uuid',p_ws);END IF;
 selected:=coalesce(nullif(p_query->>'select',''),'*');
 IF p_table='pipelines' AND op='select' AND selected='*' THEN selected:='id,owner_id,workspace_id,entity,name,is_default,stages,default_view,created_at,updated_at';END IF;
 IF selected='*' THEN SELECT array_agg(column_name::text ORDER BY ordinal_position) INTO selections FROM information_schema.columns WHERE table_schema='public' AND table_name=p_table AND column_name NOT IN('portal_token','access_token','refresh_token','oauth_tokens','credentials_secret_ref','secret') AND NOT(column_name='public_token' AND p_table IN('quotes','proposals'));ELSE selections:=string_to_array(selected,',');END IF;
 FOREACH key IN ARRAY selections LOOP
  key:=trim(key);
  IF p_table='pipelines' AND op='select' AND key='config' THEN RAISE EXCEPTION 'Configuração privada desta porta.' USING ERRCODE='42501';END IF;
  IF (key IN('portal_token','access_token','refresh_token','oauth_tokens','credentials_secret_ref','secret') OR (key='public_token' AND p_table IN('quotes','proposals'))) OR NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name=p_table AND column_name=key) THEN RAISE EXCEPTION 'Projeção da API inválida.' USING ERRCODE='42501';END IF;
  columns:=array_append(columns,quote_ident(key));
 END LOOP;
 selected:=array_to_string(columns,',');columns:=NULL;
 IF op='select' THEN
  FOR f IN SELECT * FROM jsonb_array_elements(coalesce(p_query->'order','[]')) LOOP
   key:=f->>'column';IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name=p_table AND column_name=key) OR key IN('portal_token','public_token') THEN RAISE EXCEPTION 'Ordenação inválida.';END IF;
   ordering:=ordering||CASE WHEN ordering='' THEN ' ORDER BY ' ELSE ',' END||quote_ident(key)||CASE WHEN coalesce((f->>'ascending')::boolean,true) THEN ' ASC' ELSE ' DESC' END||CASE WHEN coalesce((f->>'nullsFirst')::boolean,false) THEN ' NULLS FIRST' ELSE ' NULLS LAST' END;
  END LOOP;
  EXECUTE format('SELECT count(*) FROM %s WHERE %s',source,predicate) INTO n;
  EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(x)),''[]''::jsonb) FROM(SELECT %s FROM %s WHERE %s%s LIMIT %s OFFSET %s)x',selected,source,predicate,ordering,lim,off) INTO rows;
 ELSE
  IF op IN('insert','update') THEN
   IF jsonb_typeof(payload)<>'object' THEN RAISE EXCEPTION 'Payload inválido.';END IF;
   IF op='insert' THEN
    IF EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name=p_table AND column_name='owner_id') THEN payload:=payload||jsonb_build_object('owner_id',CASE WHEN p_table='meetings' THEN p_ws ELSE p_user END);END IF;
    IF EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name=p_table AND column_name='workspace_id') THEN payload:=payload||jsonb_build_object('workspace_id',p_ws);END IF;
   END IF;
   FOR key IN SELECT jsonb_object_keys(payload) LOOP
    IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name=p_table AND column_name=key) THEN RAISE EXCEPTION 'Campo da API inválido.';END IF;
    columns:=array_append(columns,quote_ident(key));
   END LOOP;
  END IF;
  IF op='insert' THEN
   SELECT array_agg('(jsonb_populate_record(NULL::public.'||quote_ident(p_table)||',$1)).'||x) INTO selections FROM unnest(columns)x;
   sql:=format('INSERT INTO public.%I(%s) SELECT %s RETURNING %s',p_table,array_to_string(columns,','),array_to_string(selections,','),selected);
  ELSIF op='update' THEN
   SELECT array_agg(x||'=(jsonb_populate_record(NULL::public.'||quote_ident(p_table)||',$1)).'||x) INTO selections FROM unnest(columns)x;
   sql:=format('UPDATE public.%I SET %s WHERE %s RETURNING %s',p_table,array_to_string(selections,','),predicate,selected);
  ELSE sql:=format('DELETE FROM public.%I WHERE %s RETURNING %s',p_table,predicate,selected);END IF;
  EXECUTE 'WITH changed AS ('||sql||') SELECT coalesce(jsonb_agg(to_jsonb(x)),''[]''::jsonb),count(*) FROM changed x' INTO rows,n USING payload;
 END IF;
 PERFORM techerp_api.leave();RETURN jsonb_build_object('data',rows,'count',n);
EXCEPTION WHEN OTHERS THEN
 -- enter/leave state lives inside this transaction; failed calls roll back.
 RAISE;
END $$;
ALTER FUNCTION techerp_api.sales_query(uuid,uuid,uuid,text,jsonb) OWNER TO techerp_api_subject;
REVOKE ALL ON FUNCTION techerp_api.sales_query(uuid,uuid,uuid,text,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION techerp_api.sales_query(uuid,uuid,uuid,text,jsonb) TO service_role;
CREATE OR REPLACE FUNCTION public.sales_api_query(p_key uuid,p_user uuid,p_ws uuid,p_table text,p_query jsonb)
RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path=public,pg_temp AS $$SELECT techerp_api.sales_query(p_key,p_user,p_ws,p_table,p_query)$$;
REVOKE ALL ON FUNCTION public.sales_api_query(uuid,uuid,uuid,text,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.sales_api_query(uuid,uuid,uuid,text,jsonb) TO service_role;

-- Dedicated NOLOGIN/NOBYPASSRLS owner: private columns are available only inside
-- these finite operations. It inherits caller RLS; no service-role business read.
DO $$BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='techerp_sales_tokens') THEN CREATE ROLE techerp_sales_tokens NOLOGIN INHERIT NOBYPASSRLS;END IF;END$$;
GRANT authenticated TO techerp_sales_tokens;
GRANT techerp_sales_tokens TO postgres;
GRANT USAGE,CREATE ON SCHEMA public TO techerp_sales_tokens;
GRANT SELECT(public_token),UPDATE(public_token) ON public.quotes,public.proposals TO techerp_sales_tokens;
GRANT SELECT(portal_token),UPDATE(portal_token) ON public.contacts TO techerp_sales_tokens;
CREATE OR REPLACE FUNCTION public.sales_public_token(p_table text,p_id uuid,p_rotate boolean DEFAULT false,p_purpose text DEFAULT 'share')
RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c jsonb:=sales_access_context();r text;v text;w uuid;s uuid[];j record;BEGIN
 IF p_table NOT IN('quotes','proposals','contacts') OR p_purpose NOT IN('share','send') OR coalesce((c->>'read_only')::boolean,true) THEN RAISE EXCEPTION 'Compartilhamento indisponível.' USING ERRCODE='42501';END IF;
 r:=CASE p_table WHEN 'quotes' THEN 'techsales.quote_'||p_purpose WHEN 'proposals' THEN 'techsales.proposal_'||p_purpose ELSE 'system.portal' END;
 IF NOT sales_record_access(p_table,p_id,'view') THEN RAISE EXCEPTION 'Registro indisponível.' USING ERRCODE='42501';END IF;
 IF p_table='quotes' THEN
  SELECT workspace_id,ARRAY[coalesce(assigned_to,owner_id)],public_token INTO w,s,v FROM quotes WHERE id=p_id FOR UPDATE;
 ELSIF p_table='proposals' THEN
  SELECT workspace_id,ARRAY[coalesce(assigned_to,owner_id)],public_token INTO w,s,v FROM proposals WHERE id=p_id FOR UPDATE;
 ELSE
  IF p_purpose<>'share' OR NOT sales_record_access('contacts',p_id,'update') THEN RAISE EXCEPTION 'Contato indisponível para edição.' USING ERRCODE='42501';END IF;
  SELECT workspace_id,ARRAY[coalesce(assigned_to,owner_id)],portal_token INTO w,s,v FROM contacts WHERE id=p_id FOR UPDATE;
 END IF;
 IF w IS NULL OR NOT sales_context_access(c,w,r,'manage',s) THEN RAISE EXCEPTION 'Sem permissão para compartilhar este registro.' USING ERRCODE='42501';END IF;
 IF p_rotate OR v IS NULL THEN
  v:=encode(extensions.gen_random_bytes(24),'hex');
  IF p_table='quotes' THEN UPDATE quotes SET public_token=v WHERE id=p_id;
  ELSIF p_table='proposals' THEN UPDATE proposals SET public_token=v WHERE id=p_id;
  ELSE UPDATE contacts SET portal_token=v WHERE id=p_id;END IF;
 END IF;
 RETURN v;
END $$;
ALTER FUNCTION public.sales_public_token(text,uuid,boolean,text) OWNER TO techerp_sales_tokens;
REVOKE CREATE ON SCHEMA public FROM techerp_sales_tokens;
REVOKE ALL ON FUNCTION public.sales_public_token(text,uuid,boolean,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.sales_public_token(text,uuid,boolean,text) TO authenticated;

-- Token bearer exception: service-only, no actor/tenant IDs supplied by client,
-- atomic decision on the locked published record, not a check-then-update pair.
CREATE OR REPLACE FUNCTION public.sales_public_decision(p_kind text,p_token text,p_action text,p_signature text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE q quotes;p proposals;ts timestamptz:=clock_timestamp();BEGIN
 IF length(p_token) NOT BETWEEN 16 AND 128 OR p_action NOT IN('accept','decline') THEN RAISE EXCEPTION 'Solicitação inválida.';END IF;
 IF p_kind='quotes' THEN
  SELECT * INTO q FROM quotes WHERE public_token=p_token FOR UPDATE;
  IF q.id IS NULL OR q.status::text NOT IN('published','sent') OR (q.valid_until IS NOT NULL AND q.valid_until<(ts AT TIME ZONE 'America/Sao_Paulo')::date) THEN RAISE EXCEPTION 'Cotação indisponível ou já respondida.' USING ERRCODE='42501';END IF;
  UPDATE quotes SET status=CASE WHEN p_action='accept' THEN 'accepted'::quote_status ELSE 'declined'::quote_status END,accepted_at=CASE WHEN p_action='accept' THEN ts END,declined_at=CASE WHEN p_action='decline' THEN ts END,signature_name=CASE WHEN p_action='accept' THEN nullif(left(trim(p_signature),255),'') END WHERE id=q.id;
 ELSIF p_kind='proposals' THEN
  SELECT * INTO p FROM proposals WHERE public_token=p_token FOR UPDATE;
  IF p.id IS NULL OR p.status::text<>'sent' OR NOT p.locked OR p.sent_at IS NULL OR (p.expires_at IS NOT NULL AND p.expires_at<=ts) THEN RAISE EXCEPTION 'Proposta indisponível ou já respondida.' USING ERRCODE='42501';END IF;
  UPDATE proposals SET status=CASE WHEN p_action='accept' THEN 'accepted'::proposal_status ELSE 'rejected'::proposal_status END,decided_at=ts WHERE id=p.id;
 ELSE RAISE EXCEPTION 'Documento inválido.';END IF;
 RETURN jsonb_build_object('ok',true);
END $$;
REVOKE ALL ON FUNCTION public.sales_public_decision(text,text,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.sales_public_decision(text,text,text,text) TO service_role;

CREATE OR REPLACE FUNCTION public.sales_special_capabilities(t text,ids uuid[])
RETURNS TABLE(id uuid,can_share boolean,can_send boolean)
LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=public,pg_temp AS $$
DECLARE c jsonb:=sales_access_context();j uuid;w uuid;s uuid[];prefix text;BEGIN
 IF coalesce(cardinality(ids),0)>500 THEN RAISE EXCEPTION 'Limite excedido.';END IF;
 IF t NOT IN('quotes','proposals') THEN RETURN;END IF;
 FOREACH j IN ARRAY coalesce(ids,'{}') LOOP
  IF NOT sales_record_access(t,j,'view') THEN CONTINUE;END IF;
  IF t='quotes' THEN SELECT workspace_id,ARRAY[coalesce(assigned_to,owner_id)] INTO w,s FROM quotes WHERE quotes.id=j;prefix:='techsales.quote_';
  ELSE SELECT workspace_id,ARRAY[coalesce(assigned_to,owner_id)] INTO w,s FROM proposals WHERE proposals.id=j;prefix:='techsales.proposal_';END IF;
  RETURN QUERY SELECT j,sales_context_access(c,w,prefix||'share','manage',s),sales_context_access(c,w,prefix||'send','manage',s);
 END LOOP;
END $$;
REVOKE ALL ON FUNCTION public.sales_special_capabilities(text,uuid[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.sales_special_capabilities(text,uuid[]) TO authenticated;

ALTER TABLE public.quotes ALTER COLUMN public_token SET DEFAULT encode(extensions.gen_random_bytes(24),'hex');
ALTER TABLE public.proposals ALTER COLUMN public_token SET DEFAULT encode(extensions.gen_random_bytes(24),'hex');

GRANT CREATE ON SCHEMA public TO techerp_sales_tokens;
CREATE OR REPLACE FUNCTION public.sales_portal_contacts()
RETURNS TABLE(id uuid,first_name text,last_name text,email text,portal_enabled boolean,portal_token text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c jsonb:=sales_access_context();BEGIN
 IF coalesce((c->>'read_only')::boolean,true) OR NOT(c->'keys'?'system.portal.manage.workspace') THEN RAISE EXCEPTION 'Sem permissão para gerenciar o portal.' USING ERRCODE='42501';END IF;
 RETURN QUERY SELECT x.id,x.first_name,x.last_name,x.email,x.portal_enabled,x.portal_token FROM contacts x WHERE x.workspace_id=(c->>'workspace')::uuid ORDER BY x.first_name,x.id LIMIT 1000;
END $$;
ALTER FUNCTION public.sales_portal_contacts() OWNER TO techerp_sales_tokens;
REVOKE CREATE ON SCHEMA public FROM techerp_sales_tokens;
REVOKE ALL ON FUNCTION public.sales_portal_contacts() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.sales_portal_contacts() TO authenticated;


-- Credential writes are finite, caller-scoped functions under a NOLOGIN role.
-- Values are never returned; OAuth tokens remain exclusive to trusted callbacks.
GRANT CREATE ON SCHEMA public TO techerp_sales_tokens;
GRANT INSERT(access_token),UPDATE(access_token) ON public.slack_integrations TO techerp_sales_tokens;
GRANT INSERT(credentials_secret_ref),UPDATE(credentials_secret_ref) ON public.integrations TO techerp_sales_tokens;
CREATE OR REPLACE FUNCTION public.sales_configure_integration(p_provider text,p_status text,p_config jsonb,p_credential_ref text DEFAULT NULL)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c jsonb:=sales_access_context();w uuid:=(c->>'workspace')::uuid;u uuid:=(c->>'actor')::uuid;j uuid;BEGIN
 IF NOT sales_context_access(c,w,'system.integrations','manage',ARRAY[u]) OR p_provider !~ '^[a-z][a-z0-9_-]{0,39}$' OR p_status NOT IN('connected','pending','error','disconnected') OR jsonb_typeof(p_config)<>'object' OR length(p_credential_ref)>120 THEN RAISE EXCEPTION 'Configuração não autorizada.' USING ERRCODE='42501';END IF;
 SELECT id INTO j FROM integrations WHERE workspace_id=w AND owner_id=u AND provider=p_provider FOR UPDATE;
 IF j IS NULL THEN
  PERFORM sales_area_authorize('system.integrations','create');
 ELSE
  IF NOT sales_record_access('integrations',j,'update') THEN RAISE EXCEPTION 'Integração indisponível para edição.' USING ERRCODE='42501';END IF;
  UPDATE integrations SET status=p_status::integration_status,config=p_config,credentials_secret_ref=p_credential_ref WHERE id=j;
 END IF;RETURN j;
END $$;
CREATE OR REPLACE FUNCTION public.sales_configure_slack(p_url text,p_team text DEFAULT NULL,p_channel text DEFAULT NULL)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c jsonb:=sales_access_context();w uuid:=(c->>'workspace')::uuid;u uuid:=(c->>'actor')::uuid;j uuid;BEGIN
 IF w IS NULL OR p_url !~ '^https://hooks[.]slack[.]com/services/[A-Za-z0-9/_-]+$' OR length(p_url)>2000 THEN RAISE EXCEPTION 'Webhook Slack inválido.';END IF;
 SELECT id INTO j FROM slack_integrations WHERE workspace_id=w FOR UPDATE;
 IF j IS NULL THEN
  PERFORM sales_area_authorize('system.integrations','create');
 ELSE
  IF NOT sales_record_access('slack_integrations',j,'update') THEN RAISE EXCEPTION 'Integração indisponível para edição.' USING ERRCODE='42501';END IF;
  UPDATE slack_integrations SET access_token=p_url,team_name=left(p_team,120),default_channel_name=left(p_channel,120),installed_by=u WHERE id=j;
 END IF;RETURN j;
END $$;
ALTER FUNCTION public.sales_configure_integration(text,text,jsonb,text) OWNER TO techerp_sales_tokens;
ALTER FUNCTION public.sales_configure_slack(text,text,text) OWNER TO techerp_sales_tokens;
REVOKE CREATE ON SCHEMA public FROM techerp_sales_tokens;
REVOKE ALL ON FUNCTION public.sales_configure_integration(text,text,jsonb,text),public.sales_configure_slack(text,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.sales_configure_integration(text,text,jsonb,text),public.sales_configure_slack(text,text,text) TO authenticated;
ALTER TABLE public.outbound_webhooks ALTER COLUMN secret SET DEFAULT ('whsec_'||encode(extensions.gen_random_bytes(24),'hex'));

-- Worker subject check. Source actor/workspace are read from the immutable job
-- record by a service-only wrapper, never accepted from a browser payload.
GRANT CREATE ON SCHEMA techerp_api TO techerp_api_subject;
CREATE OR REPLACE FUNCTION techerp_api.sales_worker_check(p_source text,p_id uuid,p_user uuid,p_ws uuid,p_refs jsonb)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE prev text:=current_setting('request.jwt.claims',true);c jsonb;ref jsonb;allowed boolean:=false;r text;BEGIN
 IF current_setting('app.api_subject',true)='on' OR jsonb_typeof(p_refs)<>'array' OR jsonb_array_length(p_refs)>100 THEN RAISE EXCEPTION 'Contexto de execução inválido.' USING ERRCODE='42501';END IF;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',p_user,'role','authenticated','aud','authenticated')::text,true);
 PERFORM set_config('request.jwt.claim.sub',p_user::text,true);PERFORM set_config('request.jwt.claim.role','authenticated',true);PERFORM set_config('app.api_subject','on',true);
 c:=sales_access_context();
 allowed:=c->>'actor'=p_user::text AND c->>'workspace'=p_ws::text AND sales_record_access(p_source,p_id,'view') AND sales_record_access(p_source,p_id,'update');
 IF p_source IN('whatsapp_campaigns','email_broadcasts') THEN
  allowed:=allowed AND sales_context_access(c,p_ws,'techsales.campaign_dispatch','manage',ARRAY[p_user]);
 END IF;
 FOR ref IN SELECT * FROM jsonb_array_elements(p_refs) LOOP
  IF ref->>'table' NOT IN('leads','contacts','companies','deals','whatsapp_conversations','email_threads','email_accounts','calendar_accounts','sdr_playbooks','segments','activities') OR NOT sales_record_access(ref->>'table',(ref->>'id')::uuid,'view') THEN allowed:=false;EXIT;END IF;
 END LOOP;
 PERFORM techerp_api.leave();RETURN coalesce(allowed,false);
END $$;
ALTER FUNCTION techerp_api.sales_worker_check(text,uuid,uuid,uuid,jsonb) OWNER TO techerp_api_subject;
REVOKE ALL ON FUNCTION techerp_api.sales_worker_check(text,uuid,uuid,uuid,jsonb) FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.sales_worker_authorize(p_source text,p_id uuid,p_refs jsonb DEFAULT '[]')
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE w uuid;u uuid;BEGIN
 IF p_source NOT IN('whatsapp_campaigns','email_broadcasts','sequence_enrollments','prospecting_enrollments','sdr_enrollments','enrichment_jobs','workflows') THEN RETURN false;END IF;
 EXECUTE format('SELECT workspace_id,owner_id FROM public.%I WHERE id=$1',p_source) INTO w,u USING p_id;
 IF w IS NULL OR u IS NULL THEN RETURN false;END IF;
 RETURN techerp_api.sales_worker_check(p_source,p_id,u,w,p_refs);
END $$;
REVOKE ALL ON FUNCTION public.sales_worker_authorize(text,uuid,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.sales_worker_authorize(text,uuid,jsonb) TO service_role;

-- Additional workspace settings; no direct history/worker writes.

CREATE OR REPLACE FUNCTION public.sales_source_authorize(p_actor uuid,p_ws uuid,p_resource text,p_actions text[])
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c jsonb:=work_subject_context(p_ws,p_actor);a text;BEGIN
 IF p_resource NOT IN('techsales.email_accounts','system.calendars') OR cardinality(p_actions)>2 OR NOT sales_context_access(c,p_ws,p_resource,'view',ARRAY[p_actor]) THEN RETURN false;END IF;
 FOREACH a IN ARRAY coalesce(p_actions,'{}') LOOP
  IF a IN('create','update') AND sales_context_access(c,p_ws,p_resource,a,ARRAY[p_actor]) THEN RETURN true;END IF;
 END LOOP;RETURN false;
END $$;
CREATE OR REPLACE FUNCTION public.sales_save_google_account(p_actor uuid,p_ws uuid,p_kind text,p_payload jsonb)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE target uuid;email_address text:=p_payload->>'email';r text;act text;BEGIN
 IF p_kind NOT IN('gmail','calendar') OR nullif(email_address,'') IS NULL OR length(email_address)>320 OR nullif(p_payload->>'access_token','') IS NULL THEN RAISE EXCEPTION 'Conta inválida.';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_ws::text||p_actor::text||p_kind||email_address,0));
 IF p_kind='gmail' THEN SELECT id INTO target FROM email_accounts WHERE workspace_id=p_ws AND owner_id=p_actor AND provider='gmail' AND email=email_address FOR UPDATE;r:='techsales.email_accounts';
 ELSE SELECT id INTO target FROM calendar_accounts WHERE workspace_id=p_ws AND owner_id=p_actor AND provider='google' AND email=email_address FOR UPDATE;r:='system.calendars';END IF;
 act:=CASE WHEN target IS NULL THEN 'create' ELSE 'update' END;
 IF NOT sales_source_authorize(p_actor,p_ws,r,ARRAY[act]) THEN RAISE EXCEPTION 'Permissão para conectar a conta indisponível.' USING ERRCODE='42501';END IF;
 IF p_kind='gmail' THEN
  IF target IS NULL THEN INSERT INTO email_accounts(owner_id,workspace_id,provider,email,access_token,refresh_token,expires_at,scopes,status,last_error) VALUES(p_actor,p_ws,'gmail',email_address,p_payload->>'access_token',p_payload->>'refresh_token',(p_payload->>'expires_at')::timestamptz,ARRAY(SELECT jsonb_array_elements_text(p_payload->'scopes')),'connected',NULL) RETURNING id INTO target;
  ELSE UPDATE email_accounts SET access_token=p_payload->>'access_token',refresh_token=coalesce(p_payload->>'refresh_token',refresh_token),expires_at=(p_payload->>'expires_at')::timestamptz,scopes=ARRAY(SELECT jsonb_array_elements_text(p_payload->'scopes')),status='connected',last_error=NULL WHERE id=target;END IF;
 ELSE
  IF target IS NULL THEN INSERT INTO calendar_accounts(owner_id,workspace_id,provider,email,access_token,refresh_token,expires_at,scopes,primary_calendar_id,sync_enabled,last_status,last_error) VALUES(p_actor,p_ws,'google',email_address,p_payload->>'access_token',p_payload->>'refresh_token',(p_payload->>'expires_at')::timestamptz,ARRAY(SELECT jsonb_array_elements_text(p_payload->'scopes')),'primary',true,'connected',NULL) RETURNING id INTO target;
  ELSE UPDATE calendar_accounts SET access_token=p_payload->>'access_token',refresh_token=coalesce(p_payload->>'refresh_token',refresh_token),expires_at=(p_payload->>'expires_at')::timestamptz,scopes=ARRAY(SELECT jsonb_array_elements_text(p_payload->'scopes')),sync_enabled=true,last_status='connected',last_error=NULL WHERE id=target;END IF;
 END IF;RETURN target;
END $$;
REVOKE ALL ON FUNCTION public.sales_source_authorize(uuid,uuid,text,text[]),public.sales_save_google_account(uuid,uuid,text,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.sales_source_authorize(uuid,uuid,text,text[]),public.sales_save_google_account(uuid,uuid,text,jsonb) TO service_role;
